steps.command:
cd /opt/kubespray/release-2.32 && \
/opt/kubespray/venv-release-2.32/bin/ansible-playbook -i /opt/kubespray/inventory/prod-staging/hosts.ini \
  -b --become-user=root cluster.yml -e kube_version={{version.kubernetes}}

docker compose ps
ip -br addr show | grep {{value.edgeVip}}
keepalived --version

exports.template:
# Generated by the cloud-native guide site
# Apply: kubectl -n kube-system apply -f coredns-configmap.yaml
apiVersion: v1
kind: ConfigMap
metadata:
  name: coredns
  namespace: kube-system
data:
  Corefile: |
    .:53 {
        errors
        health {
            lameduck 5s
        }
        ready
        kubernetes cluster.local in-addr.arpa ip6.arpa {
            pods insecure
            fallthrough in-addr.arpa ip6.arpa
            ttl {{value.corednsCacheTtl}}
        }
        prometheus :9153
        forward . {{value.corednsForwarders}} {
            policy {{value.corednsForwardPolicy}}
            max_concurrent 1000
        }
        cache {{value.corednsCacheTtl}}
        loop
        reload
        loadbalance
    }

# Generated by the cloud-native guide site — {{value.clusterName}} ({{value.env}})
# role	name	address
{{nodeRows}}

# Generated by the cloud-native guide site
# Edge nodes: {{value.edgeCount}} ({{edgeHostList}})

global_defs {
    router_id {{value.clusterName}}-lb
    enable_script_security
    script_user root
    vrrp_skip_check_adv_addr
}

vrrp_script chk_haproxy {
    script "/etc/keepalived/keepalived.d/check_haproxy.sh"
    interval 2
    weight -20
    fall 2
    rise 2
}

vrrp_instance VI_EDGE {
    state BACKUP
    interface bond0
    virtual_router_id 51
    priority 100
    advert_int 1

    authentication {
        auth_type PASS
        auth_pass {{vrrpAuthPass}}
    }

    unicast_src_ip {{edgeL1}}
    unicast_peer {
{{edgePeerList}}
    }

    virtual_ipaddress {
        {{value.edgeVip}}/24
    }

    track_script {
        chk_haproxy
    }

    notify_master "/etc/keepalived/keepalived.d/notify.sh MASTER"
    notify_backup "/etc/keepalived/keepalived.d/notify.sh BACKUP"
}

# Generated by the cloud-native guide site
# Namespace: {{value.appNamespace}}   Engine: {{value.vaultEngine}}

path "{{value.vaultEngine}}/apps/{{value.appNamespace}}/*" {
  capabilities = ["read"]
}

path "database/creds/{{value.appNamespace}}/*" {
  capabilities = ["read"]
}

path "pki/issue/{{value.appNamespace}}" {
  capabilities = ["create", "update"]
}
